<?php
use Aurelle\Database as DB;
$section=$data['section'];
function adminHidden(string $action,int $id=0,string $section='listings'): string { return csrf().'<input type="hidden" name="action" value="'.e($action).'"><input type="hidden" name="id" value="'.$id.'"><input type="hidden" name="section" value="'.e($section).'">'; }
?>
<div class="dashboard-layout"><aside class="dashboard-nav"><span class="eyebrow">THE ESTATE OFFICE</span><?php foreach (['listings'=>'Listing review','users'=>'Accounts & access','agents'=>'Agent applications','leads'=>'Leads & assignments','viewings'=>'Viewing records','proposals'=>'Proposal records','pricing'=>'Price change requests','providers'=>'Service providers','catalog'=>'Service catalog','business'=>'Business & branding','valuations'=>'Valuation requests','services'=>'Service operations','billing'=>'Invoices & payments','reports'=>'Reports & disputes','reviews'=>'Review moderation','categories'=>'Property categories','amenities'=>'Amenities','neighborhoods'=>'Neighborhoods','content'=>'Website content','templates'=>'Notification templates','failures'=>'Delivery failures','audit'=>'Audit history'] as $key=>$label): ?><a class="<?= $section===$key?'selected':'' ?>" href="/admin?section=<?= $key ?>"><?= $label ?></a><?php endforeach ?><a href="/dashboard">My account <?= icon('arrow') ?></a><a href="/admin/export">Export service invoices</a></aside><section class="dashboard-content"><div class="dashboard-title"><div><span class="eyebrow">ADMINISTRATION</span><h1><?= e(ucfirst($section)) ?></h1><p>Administrative actions preserve an actor and dated audit record.</p></div><a class="button small outline" href="/">View public site <?= icon('arrow') ?></a></div><div class="stats-grid"><?php foreach ($data['stats'] as $label=>$number): ?><div class="stat"><span><?= e($label) ?></span><strong><?= $number ?></strong></div><?php endforeach ?></div><form class="form-row" method="get" action="/admin"><input type="hidden" name="section" value="<?= e($section) ?>"><?php if (in_array($section,['users','listings'])): ?><input class="input" name="q" placeholder="Filter by name or title" value="<?= e($_GET['q'] ?? '') ?>"><button class="button small">Filter</button><?php endif ?><span class="tiny"><?= $data['total'] ?> records · 20 per page</span></form><br>
<?php foreach ($data['rows'] as $r): $rid=(int)($r['id'] ?? $r['user_id'] ?? 0); ?><article class="record"><div class="record-head"><h3><?= e($r['title'] ?? $r['name'] ?? $r['subject'] ?? ($section==='agents'?(DB::one('SELECT name FROM users WHERE id=?',[$rid])['name'] ?? 'Agent'):(ucfirst($section).' #'.$rid))) ?></h3><?php if (isset($r['status'])): ?><span class="badge <?= e($r['status']) ?>"><?= e($r['status']) ?></span><?php endif ?></div><div class="admin-record"><div><?php foreach ($r as $key=>$value): ?><?php if (in_array($key,['password_hash','storage_name','notification_preferences'])) continue; ?><div class="tiny"><b><?= e(str_replace('_',' ',$key)) ?>:</b> <?= e(is_string($value)?mb_substr($value,0,700):$value) ?></div><?php endforeach ?></div><div class="admin-actions">
<?php if ($section==='listings'): ?><div class="record-links"><a href="/property?id=<?= $rid ?>">Preview</a><a href="/submit?id=<?= $rid ?>">Edit details</a></div><form class="form-row" action="/admin/action" method="post"><?= adminHidden('assign',$rid,$section) ?><select class="input" name="agent_id"><?php foreach ($data['approvedAgents'] as $a): ?><option value="<?= $a['user_id'] ?>" <?= $r['agent_id']==$a['user_id']?'selected':'' ?>><?= e($a['name']) ?></option><?php endforeach ?></select><button class="button small">Assign agent</button></form><form action="/admin/action" method="post"><?= adminHidden('listing_state',$rid,$section) ?><div class="form-row"><select class="input" name="state"><?php foreach (['published','rejected','under_offer','sold','rented','withdrawn','archived'] as $state): ?><option><?= $state ?></option><?php endforeach ?></select><button class="button small">Record status</button></div><textarea class="input" name="reason" placeholder="Review reason or revision request"></textarea></form>
<?php elseif ($section==='users'): ?><form class="form-row" action="/admin/action" method="post"><?= adminHidden('suspend',$rid,$section) ?><button class="button small outline"><?= $r['suspended']?'Restore account':'Suspend account' ?></button></form><form action="/admin/action" method="post"><?= adminHidden('support_role',$rid,$section) ?><button class="button small outline">Grant restricted support role</button></form><p class="tiny">Admin creation is restricted to the local CLI. Support can review reported conversations through an audited workflow.</p>
<?php elseif ($section==='agents'): ?><form action="/admin/action" method="post"><?= adminHidden('agent_approve',$rid,$section) ?><button class="button small">Approve agent application</button></form><form action="/admin/action" method="post"><?= adminHidden('agent_verify',$rid,$section) ?><button class="button small outline">Record credential verification</button></form><p class="tiny">Verification asserts an actual administrator review. Demo profiles remain explicitly fictional.</p>
<?php elseif ($section==='services'): ?><?php if ($r['status']==='requested'): ?><form class="form-row" action="/admin/action" method="post"><?= adminHidden('quote',$rid,$section) ?><input class="input" type="number" name="amount" min="1" step=".01" required placeholder="Service quote ($)"><button class="button small">Issue quotation & invoice</button></form><?php endif ?><form action="/admin/action" method="post"><?= adminHidden('service_state',$rid,$section) ?><div class="form-row"><select class="input" name="state"><option>scheduled</option><option>completed</option><option>cancelled</option></select><input class="input" type="datetime-local" name="appointment_at" aria-label="Appointment UTC"><button class="button small">Update service</button></div></form>
<?php elseif ($section==='billing'): ?><form class="form-row" action="/admin/action" method="post"><?= adminHidden('payment',$rid,$section) ?><input class="input" type="number" name="amount" min=".01" step=".01" required placeholder="Manual payment ($)"><input class="input" name="reference" required placeholder="Unique payment reference"><button class="button small">Record manual payment</button></form><?php foreach (DB::all('SELECT * FROM payments WHERE invoice_id=?',[$rid]) as $pay): ?><p class="tiny">Payment #<?= $pay['id'] ?> · <?= money($pay['amount_minor']) ?> · <?= e($pay['reference']) ?></p><form action="/admin/action" method="post"><?= adminHidden('refund',$pay['id'],$section) ?><div class="form-row"><input class="input" name="amount" type="number" step=".01" min=".01" required placeholder="Refund amount ($)"><input class="input" name="reference" required placeholder="Unique refund reference"></div><div class="form-row"><input class="input" name="reason" required placeholder="Refund reason"><button class="button small outline">Record manual refund & credit</button></div></form><?php endforeach ?><p class="tiny">No online charge or provider refund is performed. Record only verified offline service payments.</p>
<?php elseif ($section==='valuations'): ?><form class="form-row" action="/admin/action" method="post"><?= adminHidden('valuation_assign',$rid,$section) ?><select class="input" name="agent_id"><?php foreach ($data['approvedAgents'] as $a): ?><option value="<?= $a['user_id'] ?>"><?= e($a['name']) ?></option><?php endforeach ?></select><button class="button small">Assign consultation</button></form>
<?php elseif ($section==='reviews'): ?><form class="form-row" action="/admin/action" method="post"><?= adminHidden('review_moderate',$rid,$section) ?><select class="input" name="state"><option>approved</option><option>rejected</option></select><button class="button small">Moderate review</button></form>
<?php elseif ($section==='reports'): ?><form action="/admin/action" method="post"><?= adminHidden('report_review',$rid,$section) ?><button class="button small">Open restricted report review</button></form><form action="/admin/action" method="post"><?= adminHidden('report_close',$rid,$section) ?><button class="button small outline">Close report</button></form><p class="tiny">Private messages are hidden. Restricted support permission is required to review a reported conversation. Every access is audited.</p>
<?php elseif ($section==='content'): ?><form action="/admin/action" method="post"><?= adminHidden('content',0,$section) ?><input type="hidden" name="slug" value="<?= e($r['slug']) ?>"><label class="field"><span>Page title</span><input name="title" value="<?= e($r['title']) ?>" required></label><label class="field"><span>Page content (plain text)</span><textarea name="body" required><?= e($r['body']) ?></textarea></label><button class="button small">Save public content</button></form>
<?php endif; require ROOT.'/templates/partials/admin-operations.php'; ?></div></div></article><?php endforeach; if (!$data['rows']): ?><div class="empty">No records in this section yet.</div><?php endif ?>
<?php if (in_array($section,['categories','amenities'])): ?><form class="panel form-row" action="/admin/action" method="post"><?= adminHidden($section==='categories'?'category':'amenity',0,$section) ?><input class="input" name="name" required placeholder="New <?= $section==='categories'?'property type':'amenity' ?>"><?php if ($section==='amenities'): ?><label><input type="checkbox" name="accessibility"> Accessibility feature</label><?php endif ?><button class="button small">Add</button></form><?php endif ?><?php if ($section==='templates'): ?><form class="panel" action="/admin/action" method="post"><?= adminHidden('template',0,$section) ?><label class="field"><span>Template slug</span><input name="slug" required></label><label class="field"><span>Subject</span><input name="subject" required></label><label class="field"><span>Body</span><textarea name="body" required></textarea></label><button class="button small">Save template</button></form><?php endif ?><nav class="pagination"><?php for ($page=1;$page<=ceil($data['total']/20);$page++): ?><a class="<?= $page===$data['pageNumber']?'current':'' ?>" href="/admin?<?= e(http_build_query(['section'=>$section,'page'=>$page,'q'=>$_GET['q'] ?? ''])) ?>"><?= $page ?></a><?php endfor ?></nav></section></div>
